import {avatarAssetKey} from './avatar.js?v=rig20';
import {normalizeConfig,validateConfig,escapeHtml} from './config.js?v=rig4';
let assetsPromise;
function bytesToBase64(buffer){const bytes=new Uint8Array(buffer);let binary='';const step=0x8000;for(let i=0;i<bytes.length;i+=step)binary+=String.fromCharCode(...bytes.subarray(i,i+step));return btoa(binary);}
export async function exportAssets(assetKey){
 const files=await (assetsPromise??=Promise.all(['player.bundle.js','player.css','vendor/LICENSE'].map(async path=>{const r=await fetch(new URL(path,import.meta.url));if(!r.ok)throw Error('Export asset unavailable: '+path);return r.text();})).catch(e=>{assetsPromise=null;throw e;}));
 const licensePaths=assetKey.startsWith('kay-')?['vendor/KAYKIT-LICENSE.txt']:['vendor/QUATERNIUS-LICENSE.txt','vendor/AVATAR-SDK-LICENSE.txt'];
 const licenses=await Promise.all(licensePaths.map(async path=>{const r=await fetch(new URL(path,import.meta.url));if(!r.ok)throw Error('Missing license: '+path);return r.text();}));
 const r=await fetch(new URL('assets/'+assetKey+'.glb',import.meta.url));if(!r.ok)throw Error('Character unavailable');
 return [...files,licenses.join('\n\n'),{[assetKey]:bytesToBase64(await r.arrayBuffer())}];
}
export function standaloneHtml(config,js,css,avatarAssets={}){const c=normalizeConfig(config);const errors=validateConfig(c);if(errors.length)throw Error(errors.join('\n'));const json=JSON.stringify(c).replace(/</g,'\\u003c').replace(/>/g,'\\u003e').replace(/&/g,'\\u0026');const embedded=JSON.stringify(avatarAssets).replace(/</g,'\\u003c').replace(/>/g,'\\u003e').replace(/&/g,'\\u0026');const safeJs=js.replace(/<\/script/gi,'<\\/script');return `<!doctype html>\n<html lang="${c.language}" dir="${c.language==='he'?'rtl':'ltr'}"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#152131"><title>${escapeHtml(c.profile.name)} · ${escapeHtml(c.profile.role)}</title><meta name="description" content="${escapeHtml(c.profile.introduction.slice(0,200))}"><style>${css}</style></head><body><main id="portfolio-game"></main><script id="portfolio-data" type="application/json">${json}</script><script id="avatar-assets" type="application/json">${embedded}</script><script>${safeJs}</script></body></html>`;}
export function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
export const projectName=c=>(c.profile.name.trim().replace(/[^\p{L}\p{N}\s_-]/gu,'').replace(/\s+/g,'-').slice(0,60)||'portfolio')+'-portfolio';
export const projectJSON=c=>JSON.stringify(normalizeConfig(c),null,2);
const encoder=new TextEncoder();let crcTable;
function crc32(bytes){crcTable??=Uint32Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0;});let crc=0xffffffff;for(const b of bytes)crc=crcTable[(crc^b)&255]^(crc>>>8);return (crc^0xffffffff)>>>0;}
// Standard ZIP with stored entries: no runtime dependency or network is needed.
export function createZip(files){const chunks=[],central=[];let offset=0;for(const [filename,text]of Object.entries(files)){const name=encoder.encode(filename),data=encoder.encode(text),crc=crc32(data);const local=new Uint8Array(30+name.length),l=new DataView(local.buffer);l.setUint32(0,0x04034b50,true);l.setUint16(4,20,true);l.setUint16(6,0x800,true);l.setUint32(14,crc,true);l.setUint32(18,data.length,true);l.setUint32(22,data.length,true);l.setUint16(26,name.length,true);local.set(name,30);chunks.push(local,data);const header=new Uint8Array(46+name.length),h=new DataView(header.buffer);h.setUint32(0,0x02014b50,true);h.setUint16(4,20,true);h.setUint16(6,20,true);h.setUint16(8,0x800,true);h.setUint32(16,crc,true);h.setUint32(20,data.length,true);h.setUint32(24,data.length,true);h.setUint16(28,name.length,true);h.setUint32(42,offset,true);header.set(name,46);central.push(header);offset+=local.length+data.length;}
 const size=central.reduce((a,b)=>a+b.length,0),end=new Uint8Array(22),v=new DataView(end.buffer);v.setUint32(0,0x06054b50,true);v.setUint16(8,central.length,true);v.setUint16(10,central.length,true);v.setUint32(12,size,true);v.setUint32(16,offset,true);return new Blob([...chunks,...central,end],{type:'application/zip'});
}
export async function exportPortfolio(config,format){const snapshot=normalizeConfig(config);const [js,css,license,humanLicense,avatarAssets]=await exportAssets(avatarAssetKey(snapshot.avatar));const html=standaloneHtml(snapshot,js,css,avatarAssets);const name=projectName(snapshot);if(format==='html'){downloadBlob(new Blob([html],{type:'text/html;charset=utf-8'}),name+'.html');return;}
 const readme=`PORTFOLIO STUDIO — YOUR PLAYABLE PORTFOLIO\n\nOpen index.html in a modern browser with WebGL enabled. No server or internet connection is required to play. External links you added still require the internet.\n\nControls: W/S or up/down to walk; A/D or left/right to turn; drag to look; Shift to run; Space to jump; Enter near a station to open it; Esc to close.\n\nTo publish: upload index.html to any static website host. This download does not create a public link automatically. Your exported file includes the résumé and contact details you entered. Review them before sharing.\n\nTo edit later: open portfolio-project.json in Portfolio Studio using Open project. The project file is editable data, not a playable game.\n\nThree.js is included under the MIT license; see THREE-LICENSE.txt. Additional KayKit characters by Kay Lousberg are CC0; see CHARACTER-LICENSE.txt.\n\nעברית\nפתחו את index.html בדפדפן מודרני עם WebGL. המשחק פועל גם ללא חיבור לאינטרנט. קישורים חיצוניים דורשים חיבור.\nכדי להמשיך לערוך, טענו את portfolio-project.json באמצעות פתיחת פרויקט במערכת.\nכדי לפרסם באתר, העלו את index.html לשירות לאחסון אתרים סטטיים. הייצוא אינו יוצר קישור ציבורי אוטומטית. הקובץ כולל את התוכן ופרטי הקשר שהזנתם; בדקו אותם לפני השיתוף.\n`;
 downloadBlob(createZip({'index.html':html,'portfolio-project.json':projectJSON(snapshot),'README.txt':readme,'THREE-LICENSE.txt':license,'CHARACTER-LICENSE.txt':humanLicense}),name+'.zip');
}
